// Import of required libraries
import { expect, test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openOwnersList } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await openOwnersList(page, baseUrl);
    await page.locator("a[href=\"/petclinic/owners/1\"]").click();
    await page.getByRole("button", { name: "Edit Owner" }).click();

    // The PR adds the Email field to the edit form. The input renders, but
    // OwnerEditComponent never notifies change detection after getOwnerById resolves,
    // so the form loads blank and the stored address is never pre-filled.
    await expect(page.locator("#email")).toHaveValue('george.franklin@example.com');
});
